/** The Rust epi kernel, loaded once. Experiment 161.
 *
 *  Top-level await so every caller can stay synchronous: a measure is arithmetic, and making each
 *  one async would change every step above it for nothing. The bytes are embedded, so there is no
 *  fetch that can fail offline. If this cannot instantiate the module fails to load, which is
 *  right: a kernel that quietly returned nothing would be worse than an application that stops. */
import {KERNEL_BASE64} from './kernel-bytes.js';

type Cells=(a:number,b:number,c:number,d:number)=>number;
type Bound=(a:number,b:number,c:number,d:number,z:number)=>number;
export interface Kernel {
  risk_ratio:Cells; odds_ratio:Cells; risk_difference:Cells; rate_ratio:Cells;
  risk_ratio_ci_lower:Bound; risk_ratio_ci_upper:Bound;
  odds_ratio_ci_lower:Bound; odds_ratio_ci_upper:Bound;
  risk_difference_ci_lower:Bound; risk_difference_ci_upper:Bound;
  rate_ratio_ci_lower:Bound; rate_ratio_ci_upper:Bound;
  // Regression, experiment 167: a design set row by row, fitted, then read back.
  glm_reset(rows:number,cols:number):number; glm_set_x(row:number,col:number,value:number):number;
  glm_set_row(row:number,outcome:number,offset:number,stratum:number):number;
  glm_fit(family:number,stratified:number,maxIter:number,tol:number):number;
  glm_coefficient(col:number):number; glm_covariance(row:number,col:number):number;
  glm_hac_covariance(col:number,other:number,lag:number,stratified:number):number;
  glm_iterations():number; glm_loglik():number; glm_pearson():number;
  glm_used_rows():number; glm_used_strata():number; glm_dropped_strata():number; glm_fitted_value(row:number):number;
  // The space-time scan's test (TODO 17, step 3): arrays laid out, written through scan_ptr, shuffles run in batches.
  memory:WebAssembly.Memory;
  scan_prepare(n:number,places:number,bins:number,centers:number,circles:number,order:number,replications:number):number;
  scan_ptr(which:number):number; scan_begin(seed:number):void;
  scan_run(count:number,top:number,stopAfter:number,longest:number,prospective:number):number;
  // An agent-based model of an outbreak (experiment 199's spike): households and classes written through abm_ptr, one
  // run per seed, the daily counts of S, E, I and R read back at abm_ptr(5). abm_run's count comes back signed: read it
  // with >>>0, where 4294967295 means the parameters were refused.
  abm_prepare(n:number,days:number):number; abm_ptr(which:number):number;
  abm_run(seed:bigint,index:number,pHousehold:number,pClass:number,pVillage:number,latentMin:number,latentMax:number,
    infectiousMin:number,infectiousMax:number):number;
  // A disease model declared as data (experiment 220's spike): see src/disease-model.ts, which lays a declaration out
  // through decl_ptr and reads decl_run's count unsigned.
  decl_prepare(n:number,days:number,nets:number,steps:number,states:number):number; decl_ptr(which:number):number;
  decl_run(seed:bigint,index:number,susceptible:number,infected:number,infectious:number):number;
  // A raster totalled over areas, one strip of rows at a time (src/raster-stream.ts, 2026-11-19).
  zonal_prepare(areas:number,edges:number,width:number,strip:number,bins:number,collect:number):number;
  zonal_ptr(which:number):number; zonal_begin(mode:number):number;
  zonal_rows(first:number,rows:number,values:number,mode:number,noData:number,hasNoData:number):number;
  // A kernel density surface (experiment 225's spike, src/density.ts): points (x, y, weight) at density_ptr(0), the grid at
  // density_ptr(1); density_run's count comes back signed, read with >>>0, where 4294967295 means the bandwidth was refused.
  density_prepare(points:number,width:number,height:number):number; density_ptr(which:number):number; density_run(bandwidth:number):number;
}
const bytes=Uint8Array.from(atob(KERNEL_BASE64),character=>character.charCodeAt(0));
export const kernel=(await WebAssembly.instantiate(bytes,{})).instance.exports as unknown as Kernel;
